-- Professional role and skill taxonomy from LoopsKey_Roles_Skills.xlsx
-- (catalogue version 1, source sha256 37bb2e362dc88cc783305e35ed4e3260437aea62cb1ac2387b0b15f29b97acb8).
--
-- Production applies migrations, not seeds, so the catalogue ships here. The
-- same rows are generated from prisma/seeds/data/profile-taxonomy.catalog.json
-- and re-applied idempotently by the profile taxonomy seed.
--
-- Categories become first-class ProfileTaxonomyGroup rows. Existing terms keep
-- their ids, so every ProfessionalProfileTerm stays valid. A ROLE or SKILL_AREA
-- term that is not in the catalogue is deactivated, never deleted: profiles
-- that selected it still show it, and it can no longer be chosen. Subjects are
-- untouched apart from moving onto group rows.

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ---------------------------------------------------------------------------
-- 1. Category rows, first from the categories terms already carry.
-- ---------------------------------------------------------------------------
CREATE TABLE "ProfileTaxonomyGroup" (
    "id" TEXT NOT NULL,
    "kind" "ProfileTaxonomyKind" NOT NULL,
    "key" TEXT NOT NULL,
    "label" TEXT NOT NULL,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ProfileTaxonomyGroup_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ProfileTaxonomyGroup_kind_key_key" ON "ProfileTaxonomyGroup"("kind", "key");
CREATE INDEX "ProfileTaxonomyGroup_kind_isActive_sortOrder_idx" ON "ProfileTaxonomyGroup"("kind", "isActive", "sortOrder");

SELECT
    'ptg_' || CASE term."kind"
        WHEN 'ROLE' THEN 'role'
        WHEN 'SKILL_AREA' THEN 'skill'
        ELSE 'subject'
    END || '_' || lower(term."groupKey"),
    term."kind",
    term."groupKey",
    min(term."groupLabel"),
    min(term."sortOrder") / 100,
    true,
    CURRENT_TIMESTAMP
FROM "ProfileTaxonomyTerm" AS term
GROUP BY term."kind", term."groupKey";

ALTER TABLE "ProfileTaxonomyTerm" ADD COLUMN "groupId" TEXT;

UPDATE "ProfileTaxonomyTerm" AS term
SET "groupId" = taxonomy_group."id"
FROM "ProfileTaxonomyGroup" AS taxonomy_group
WHERE taxonomy_group."kind" = term."kind"
  AND taxonomy_group."key" = term."groupKey";

ALTER TABLE "ProfileTaxonomyTerm" ALTER COLUMN "groupId" SET NOT NULL;

DROP INDEX IF EXISTS "ProfileTaxonomyTerm_groupKey_idx";
DROP INDEX IF EXISTS "ProfileTaxonomyTerm_kind_isActive_idx";
ALTER TABLE "ProfileTaxonomyTerm" DROP COLUMN "groupKey";
ALTER TABLE "ProfileTaxonomyTerm" DROP COLUMN "groupLabel";

-- ---------------------------------------------------------------------------
-- 2. The approved catalogue.
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE "catalogue_group" ("id" TEXT, "kind" TEXT, "key" TEXT, "label" TEXT, "sortOrder" INTEGER) ON COMMIT DROP;
CREATE TEMP TABLE "catalogue_term" ("id" TEXT, "kind" TEXT, "key" TEXT, "label" TEXT, "groupKey" TEXT, "sortOrder" INTEGER) ON COMMIT DROP;



SELECT "id", "kind"::"ProfileTaxonomyKind", "key", "label", "sortOrder", true, CURRENT_TIMESTAMP
FROM "catalogue_group"
ON CONFLICT ("kind", "key") DO UPDATE
SET "label" = EXCLUDED."label",
    "sortOrder" = EXCLUDED."sortOrder",
    "isActive" = true,
    "updatedAt" = CURRENT_TIMESTAMP;

SELECT catalogue."id", catalogue."kind"::"ProfileTaxonomyKind", catalogue."key", catalogue."label",
       taxonomy_group."id", catalogue."sortOrder", true, CURRENT_TIMESTAMP
FROM "catalogue_term" AS catalogue
JOIN "ProfileTaxonomyGroup" AS taxonomy_group
  ON taxonomy_group."kind" = catalogue."kind"::"ProfileTaxonomyKind"
 AND taxonomy_group."key" = catalogue."groupKey"
ON CONFLICT ("kind", "key") DO UPDATE
SET "label" = EXCLUDED."label",
    "groupId" = EXCLUDED."groupId",
    "sortOrder" = EXCLUDED."sortOrder",
    "isActive" = true,
    "updatedAt" = CURRENT_TIMESTAMP;

UPDATE "ProfileTaxonomyTerm" AS term
SET "isActive" = false, "updatedAt" = CURRENT_TIMESTAMP
WHERE term."kind" IN ('ROLE', 'SKILL_AREA')
  AND term."isActive" = true
  AND NOT EXISTS (
    SELECT 1 FROM "catalogue_term" AS catalogue
    WHERE catalogue."kind"::"ProfileTaxonomyKind" = term."kind"
      AND catalogue."key" = term."key"
  );

UPDATE "ProfileTaxonomyGroup" AS taxonomy_group
SET "isActive" = false, "updatedAt" = CURRENT_TIMESTAMP
WHERE taxonomy_group."kind" IN ('ROLE', 'SKILL_AREA')
  AND taxonomy_group."isActive" = true
  AND NOT EXISTS (
    SELECT 1 FROM "catalogue_group" AS catalogue
    WHERE catalogue."kind"::"ProfileTaxonomyKind" = taxonomy_group."kind"
      AND catalogue."key" = taxonomy_group."key"
  );

ALTER TABLE "ProfileTaxonomyTerm"
    ADD CONSTRAINT "ProfileTaxonomyTerm_groupId_fkey"
    FOREIGN KEY ("groupId") REFERENCES "ProfileTaxonomyGroup"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE INDEX "ProfileTaxonomyTerm_kind_isActive_sortOrder_idx" ON "ProfileTaxonomyTerm"("kind", "isActive", "sortOrder");
CREATE INDEX "ProfileTaxonomyTerm_groupId_isActive_sortOrder_idx" ON "ProfileTaxonomyTerm"("groupId", "isActive", "sortOrder");

-- Unmanaged: backs the case-insensitive substring search on term labels.
CREATE INDEX IF NOT EXISTS "ProfileTaxonomyTerm_label_trgm_idx"
    ON "ProfileTaxonomyTerm" USING GIN ("label" gin_trgm_ops);

-- ---------------------------------------------------------------------------
-- 3. Role category -> skill category suggestions (mapping version 1).
-- ---------------------------------------------------------------------------
CREATE TABLE "ProfileTaxonomyGroupMapping" (
    "id" TEXT NOT NULL,
    "roleGroupId" TEXT NOT NULL,
    "skillGroupId" TEXT NOT NULL,
    "priority" INTEGER NOT NULL,
    "version" INTEGER NOT NULL,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ProfileTaxonomyGroupMapping_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ProfileTaxonomyGroupMapping_roleGroupId_skillGroupId_key" ON "ProfileTaxonomyGroupMapping"("roleGroupId", "skillGroupId");
CREATE INDEX "ProfileTaxonomyGroupMapping_roleGroupId_isActive_priority_idx" ON "ProfileTaxonomyGroupMapping"("roleGroupId", "isActive", "priority");

ALTER TABLE "ProfileTaxonomyGroupMapping"
    ADD CONSTRAINT "ProfileTaxonomyGroupMapping_roleGroupId_fkey"
    FOREIGN KEY ("roleGroupId") REFERENCES "ProfileTaxonomyGroup"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "ProfileTaxonomyGroupMapping"
    ADD CONSTRAINT "ProfileTaxonomyGroupMapping_skillGroupId_fkey"
    FOREIGN KEY ("skillGroupId") REFERENCES "ProfileTaxonomyGroup"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

