-- ---------------------------------------------------------------------------
-- 4. A canonical identity for the current role.
-- ---------------------------------------------------------------------------
ALTER TABLE "ProfessionalProfile" ADD COLUMN "currentRoleTermId" TEXT;

CREATE INDEX "ProfessionalProfile_currentRoleTermId_idx" ON "ProfessionalProfile"("currentRoleTermId");

ALTER TABLE "ProfessionalProfile"
    ADD CONSTRAINT "ProfessionalProfile_currentRoleTermId_fkey"
    FOREIGN KEY ("currentRoleTermId") REFERENCES "ProfileTaxonomyTerm"("id")
    ON DELETE SET NULL ON UPDATE CASCADE;

-- Only an unambiguous, case-insensitive exact match is linked; anything else
-- stays as the custom text it already is.
UPDATE "ProfessionalProfile" AS profile
SET "currentRoleTermId" = candidate."id",
    "currentRole" = candidate."label"
FROM (
    SELECT lower(btrim(term."label")) AS "normalized",
           min(term."id") AS "id",
           min(term."label") AS "label",
           count(*) AS "matches"
    FROM "ProfileTaxonomyTerm" AS term
    WHERE term."kind" = 'ROLE' AND term."isActive" = true
    GROUP BY lower(btrim(term."label"))
) AS candidate
WHERE candidate."matches" = 1
  AND profile."currentRoleTermId" IS NULL
  AND profile."currentRole" IS NOT NULL
  AND lower(btrim(profile."currentRole")) = candidate."normalized";
